{
  "findings": [
    {
      "check_id": "CKV_AZURE_36",
      "title": "Ensure 'Trusted Microsoft Services' is enabled for Storage Account access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not have 'Trusted Microsoft Services' enabled for access, potentially allowing unauthorized access."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account allows anonymous access to blobs, which could lead to unintended data exposure."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n  allow_blob_public_access  = false\n  network_rules {\n    bypass = [\"AzureServices\"]\n    default_action = \"Deny\"\n  }\n}",
  "fix_summary": "Enabled 'Trusted Microsoft Services' access and disabled blob anonymous access for the storage account, and enforced HTTPS traffic only."
}
